/**
 * Human wording for run and node states. The wording deliberately separates "this node finished" from
 * "this workflow is complete": only a `succeeded` run is complete, and a worker node's success only means
 * its native session launched and ended its turn.
 */
import { isBlockingFinding, type ReviewResult, type RunDetail } from './api.ts'

export type RunStatus = RunDetail['summary']['status']
export type NodeKind = RunDetail['definition']['nodes'][number]['kind']

export const STATUS_LABEL: Record<RunStatus, string> = {
  pending: 'Pending',
  running: 'Running',
  awaiting_approval: 'Awaiting approval',
  paused: 'Paused',
  succeeded: 'Succeeded',
  failed: 'Failed',
  cancelled: 'Cancelled',
}

/** What a run in this status means for the workflow as a whole. */
export const RUN_STATUS_MEANING: Record<RunStatus, string> = {
  pending: 'Nothing has started yet.',
  running: 'Work is in progress. The workflow is not complete.',
  awaiting_approval: 'Stopped at a decision that has not been made. The workflow is not complete; nothing is approved by viewing it.',
  paused: 'Paused with unresolved state (for example a session that could not be reconciled). The workflow is not complete.',
  succeeded: 'Integration was confirmed and no graph work remains.',
  failed: 'A graph step or check failed. The workflow did not complete.',
  cancelled: 'The run was cancelled before completion.',
}

/** What a node in this status means, given its kind. */
export function nodeStatusMeaning(kind: NodeKind, status: RunStatus): string {
  switch (status) {
    case 'pending': return 'Not started: no attempt has run.'
    case 'running': return kind === 'worker' ? 'The native worker session is running or its turn has not been signalled complete.' : 'In progress.'
    case 'awaiting_approval': return 'Waiting for an explicit decision recorded outside this viewer. Not complete.'
    case 'paused': return 'Paused with unresolved evidence. Not complete.'
    case 'succeeded':
      return kind === 'worker'
        ? 'The worker session launched and ended its turn. This is not workflow completion; verification, review and integration are separate nodes.'
        : kind === 'integration'
          ? 'This integration step completed.'
          : 'This step completed.'
    case 'failed': return 'This step failed. The run cannot succeed without intervention.'
    case 'cancelled': return 'This step was cancelled.'
  }
}

export const KIND_LABEL: Record<NodeKind, string> = {
  prepare: 'Preparation',
  worker: 'Worker',
  verification: 'Verification',
  review: 'Review',
  integration: 'Integration',
}

export function shortRevision(revision: string): string {
  return revision.slice(0, 12)
}

export function formatTime(iso: string): string {
  const time = Date.parse(iso)
  if (Number.isNaN(time)) return iso
  return new Date(time).toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC')
}

/** Compact duration for deadlines and timeouts: 14400 → "4h", 5400 → "1h30m", 45 → "45s". */
export function formatDuration(seconds: number): string {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const rest = seconds % 60
  const parts: string[] = []
  if (hours > 0) parts.push(`${hours}h`)
  if (minutes > 0) parts.push(`${minutes}m`)
  if (rest > 0 || parts.length === 0) parts.push(`${rest}s`)
  return parts.join('')
}

/** The automatic profile's deadlines as one phrase, e.g. "worker 4h · review 30m". */
export function deadlinesLabel(automatic: { worker_timeout_seconds: number; review_timeout_seconds: number }): string {
  return `worker ${formatDuration(automatic.worker_timeout_seconds)} · review ${formatDuration(automatic.review_timeout_seconds)}`
}

const DISPOSITIONS = ['open', 'resolved', 'accepted'] as const

/** One line for a recorded review: verdict, finding counts by disposition and how many block integration (unresolved P0/P1). */
export function reviewSummary(review: ReviewResult): string {
  const { verdict, findings } = review
  if (findings.length === 0) return `${verdict} with no findings`
  const counts = DISPOSITIONS
    .map(disposition => [disposition, findings.filter(finding => finding.disposition === disposition).length] as const)
    .filter(([, count]) => count > 0)
    .map(([disposition, count]) => `${count} ${disposition}`)
  const blocking = findings.filter(isBlockingFinding).length
  return `${verdict} with ${findings.length} ${findings.length === 1 ? 'finding' : 'findings'}: ${counts.join(', ')}, ${blocking === 0 ? 'none blocking' : `${blocking} blocking`}`
}
import { useMemo, type KeyboardEvent } from 'react'
import { DAG_NODE_HEIGHT, DAG_NODE_WIDTH, layoutDag } from './dag.ts'
import { KIND_LABEL, STATUS_LABEL, type NodeKind, type RunStatus } from './status.ts'
import { wrapLabel } from '../graph/labels.ts'

export type GraphNodeView = {
  node_id: string
  label: string
  kind: NodeKind
  depends_on: string[]
  /** Absent for a definition without a run (current workflow definition). */
  status?: RunStatus
  attempt?: number
}

type Props = {
  /** Identifies what the picture shows, e.g. "Pinned definition of run-001". */
  title: string
  nodes: GraphNodeView[]
  selectedId: string | null
  /** When omitted, the graph is a static picture of a definition. */
  onSelect?: (nodeId: string) => void
}

/**
 * Layered SVG rendering of a workflow definition, optionally coloured by a run's node statuses. Every node
 * is a keyboard-focusable control describing its label, kind, status and attempt; the surrounding node
 * list is the equivalent non-graphical view.
 */
export function WorkflowGraph({ title, nodes, selectedId, onSelect }: Props) {
  const layout = useMemo(() => layoutDag(nodes), [nodes])
  const interactive = onSelect !== undefined

  const keyHandler = (nodeId: string, index: number) => (event: KeyboardEvent<SVGGElement>) => {
    if (!interactive) return
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      onSelect(nodeId)
      return
    }
    const delta = event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : event.key === 'ArrowLeft' || event.key === 'ArrowUp' ? -1 : 0
    if (delta === 0) return
    event.preventDefault()
    const next = nodes[(index + delta + nodes.length) % nodes.length]
    const target = event.currentTarget.ownerSVGElement?.querySelector<SVGGElement>(`[data-graph-node="${CSS.escape(next.node_id)}"]`)
    target?.focus()
  }

  return (
    <div className="workflow-graph-scroll">
      <svg
        className="workflow-graph"
        role="group"
        aria-label={title}
        viewBox={`0 0 ${layout.width} ${layout.height}`}
        width={layout.width}
        height={layout.height}
        data-testid="workflow-graph"
      >
        <defs>
          <marker id="workflow-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse">
            <path d="M 0 0 L 10 5 L 0 10 z" className="workflow-edge-arrow" />
          </marker>
        </defs>
        {layout.edges.map(edge => {
          const from = layout.positions.get(edge.from)!
          const to = layout.positions.get(edge.to)!
          const x1 = from.x + DAG_NODE_WIDTH
          const y1 = from.y + DAG_NODE_HEIGHT / 2
          const x2 = to.x
          const y2 = to.y + DAG_NODE_HEIGHT / 2
          const bend = (x2 - x1) / 2
          return (
            <path
              key={`${edge.from}->${edge.to}`}
              className="workflow-edge"
              d={`M ${x1} ${y1} C ${x1 + bend} ${y1}, ${x2 - bend} ${y2}, ${x2} ${y2}`}
              markerEnd="url(#workflow-arrow)"
              data-edge-from={edge.from}
              data-edge-to={edge.to}
            />
          )
        })}
        {nodes.map((node, index) => {
          const position = layout.positions.get(node.node_id)!
          const status = node.status
          const lines = wrapLabel(node.label, 18, 2)
          const description = [
            node.label,
            KIND_LABEL[node.kind].toLowerCase(),
            status ? STATUS_LABEL[status].toLowerCase() : null,
            node.attempt !== undefined ? `attempt ${node.attempt}` : null,
          ].filter(Boolean).join(', ')
          const className = [
            'workflow-node',
            `workflow-node-${node.kind}`,
            status ? `is-${status}` : 'is-definition',
            node.node_id === selectedId ? 'is-selected' : '',
          ].filter(Boolean).join(' ')
          return (
            <g
              key={node.node_id}
              className={className}
              transform={`translate(${position.x} ${position.y})`}
              data-graph-node={node.node_id}
              data-status={status ?? 'definition'}
              role={interactive ? 'button' : undefined}
              tabIndex={interactive ? 0 : undefined}
              aria-label={description}
              aria-pressed={interactive ? node.node_id === selectedId : undefined}
              onClick={interactive ? () => onSelect(node.node_id) : undefined}
              onKeyDown={keyHandler(node.node_id, index)}
            >
              <rect className="workflow-node-shape" width={DAG_NODE_WIDTH} height={DAG_NODE_HEIGHT} rx="8" />
              <rect className="workflow-node-focus" x="-3" y="-3" width={DAG_NODE_WIDTH + 6} height={DAG_NODE_HEIGHT + 6} rx="10" />
              <rect className="workflow-node-status-bar" x="0" y="0" width="6" height={DAG_NODE_HEIGHT} rx="3" />
              <text className="workflow-node-label" x="14" y={lines.length === 1 ? 24 : 20} aria-hidden="true">
                {lines.map((line, lineIndex) => (
                  <tspan key={lineIndex} x="14" dy={lineIndex === 0 ? 0 : 14}>{line}</tspan>
                ))}
              </text>
              <text className="workflow-node-meta" x="14" y={DAG_NODE_HEIGHT - 10} aria-hidden="true">
                {status ? `${STATUS_LABEL[status]}${node.attempt !== undefined ? ` · attempt ${node.attempt}` : ''}` : KIND_LABEL[node.kind]}
              </text>
              {!interactive && <title>{description}</title>}
            </g>
          )
        })}
      </svg>
    </div>
  )
}
/**
 * How review findings are attributed to the lanes a run actually had. A finding's `worker` is a lane id, `multiple`
 * or `none`; exports of two-lane runs recorded `both`, which reads as `multiple`; null predates the vocabulary.
 * Pure helpers, kept out of the component file so it only exports components.
 */
import type { ReviewFinding, RunDetail, RunInputs } from './api.ts'
import type { Resource } from './useResource.ts'

type DefinitionNode = RunDetail['definition']['nodes'][number]

const MULTIPLE = 'multiple'
const LEGACY_MULTIPLE = 'both'
const NONE = 'none'
const UNRECORDED = 'unrecorded'
const SPECIAL_GROUPS: readonly string[] = [MULTIPLE, NONE, UNRECORDED]
const SPECIAL_LABEL: Record<string, string> = { [MULTIPLE]: 'Multiple workers', [NONE]: 'No worker (cross-cutting)', [UNRECORDED]: 'Worker not recorded' }

/** The group a finding belongs to when grouped by worker: a lane id, `multiple` (also for legacy `both`), `none` or `unrecorded`. */
export function workerGroupOf(finding: Pick<ReviewFinding, 'worker'>): string {
  if (finding.worker === null) return UNRECORDED
  if (finding.worker === LEGACY_MULTIPLE) return MULTIPLE
  return finding.worker
}

/** The Worker column wording: lane ids verbatim, the multi-lane values as words. */
export function workerWording(worker: string): string {
  if (worker === MULTIPLE || worker === LEGACY_MULTIPLE) return 'multiple workers'
  if (worker === NONE) return 'none'
  return worker
}

/**
 * The run's lanes in policy order: from the recorded inputs when loaded, else from the pinned graph's `launch_<id>`
 * nodes (the naming the exporter guarantees), so findings group by lane even for a run whose inputs are not recorded.
 */
export function runLanes(definitionNodes: DefinitionNode[], inputs: Resource<RunInputs | null>): string[] {
  if (inputs.status === 'ready' && inputs.data !== null) return inputs.data.workers.map(worker => worker.node_id)
  return definitionNodes.filter(node => node.kind === 'worker' && node.node_id.startsWith('launch_')).map(node => node.node_id.slice('launch_'.length))
}

/**
 * Worker groups in display order: the run's lanes, then any lane id a finding names that the run does not list
 * (never dropped), then `multiple`, `none` and `unrecorded`. Only populated groups are rendered.
 */
export function workerGroups(lanes: readonly string[], findings: readonly Pick<ReviewFinding, 'worker'>[]): { key: string; label: string }[] {
  const keys = [...lanes]
  for (const finding of findings) {
    const group = workerGroupOf(finding)
    if (!keys.includes(group) && !SPECIAL_GROUPS.includes(group)) keys.push(group)
  }
  return [...keys.map(lane => ({ key: lane, label: `Worker ${lane}` })), ...SPECIAL_GROUPS.map(key => ({ key, label: SPECIAL_LABEL[key] }))]
}

