 */
import { test, expect, type APIRequestContext, type Locator, type Page, type TestInfo } from '@playwright/test'
import { waitForApi } from '../helpers.ts'
import { apiRunPath, PROJECT, WORKFLOW_ID } from './fixtures.ts'
import { verificationPhase } from './harness.ts'
import { installProjectMocks } from './mock.ts'

export const phase = verificationPhase()

export const projectsUrl = '/projects'
export const projectUrl = (projectId: string) => `/projects/${encodeURIComponent(projectId)}`
export const workflowUrl = (projectId: string, workflowId: string) => `${projectUrl(projectId)}/workflows/${encodeURIComponent(workflowId)}`
export const runUrl = (runId: string, nodeId?: string, workflowId: string = WORKFLOW_ID) => `${workflowUrl(PROJECT.project_id, workflowId)}/runs/${encodeURIComponent(runId)}${nodeId ? `/nodes/${encodeURIComponent(nodeId)}` : ''}`
export const apiRun = apiRunPath

export const workspace = (page: Page) => page.getByTestId('projects-workspace')
export const graphNode = (page: Page, nodeId: string) => page.locator(`[data-testid="workflow-graph"] [data-graph-node="${nodeId}"]`)
export const nodeListItem = (page: Page, nodeId: string) => page.locator(`[data-testid="run-node-list"] [data-node-id="${nodeId}"]`)
export const nodeDetail = (page: Page) => page.getByTestId('node-detail')

/** No view action may launch, approve, retry, delete or edit a run: no such real controls exist (graph nodes are read-only selectors). */
export async function expectNoExecutionControls(page: Page) {
  const controls = workspace(page).locator('button, input, select, textarea, [role="menuitem"]')
  await expect(controls.filter({ hasText: /approve|retry|launch|start|resume|delete|cancel|integrate|edit|save/i })).toHaveCount(0)
  await expect(page.locator('form')).toHaveCount(0)
}

export async function attach(page: Page, testInfo: TestInfo, id: string) {
  const image = testInfo.outputPath(`${id}.png`)
  await page.screenshot({ path: image, fullPage: true })
  await testInfo.attach(`screenshot:${id}`, { path: image, contentType: 'image/png' })
}

export async function waitForProjectsApi(request: APIRequestContext) {
  if (phase !== 'candidate') return
  await expect.poll(async () => (await request.get('/api/projects')).status(), { timeout: 30_000 }).toBe(200)
}

/** Registers the suite's shared per-test setup; call once at the top level of a spec file. */
export function installHooks() {
  test.beforeEach(async ({ page, request }) => {
    await waitForApi(request)
    await waitForProjectsApi(request)
    if (phase === 'worker') await installProjectMocks(page)
  })
}

/** Reads the rendered text and asserts no absolute filesystem path (temporary root or home) leaked into it. */
export async function renderedText(locator: Locator): Promise<string> {
  const text = await locator.innerText()
  expect(text, 'rendered text must not name a temporary or home directory').not.toMatch(/\/tmp\/|\/home\//)
  return text
}

/** Fetches a URL from inside the page, so worker-mode route mocks apply exactly as they do for the app. */
export async function fetchFromPage(page: Page, url: string): Promise<{ status: number; contentType: string | null; text: string }> {
  return page.evaluate(async target => {
    const response = await fetch(target)
    return { status: response.status, contentType: response.headers.get('content-type'), text: await response.text() }
  }, url)
}
# Ready-to-launch feature: project workflows and run viewer

This directory is the committed assignment for the feature's worker lanes, **not** an implementation of the Projects feature. The API contract is `contracts/projects/README.md`.

`feature.json` (version 2.0.0, `contracts/workflow/feature.schema.json`) declares the lanes and their task files: `ui` (`ui-task.md`) and `adapter` (`adapter-task.md`). It declares no `reviewers`, so the run has the single built-in reviewer `review` (`workflow/prompts/review.md`) and none of its file names change. `reviewers/` holds example briefs a 2.1.0 feature file can declare (`{"reviewers": [{"reviewer_id": "general", "prompt": "reviewers/general.md"}, {"reviewer_id": "coverage", "prompt": "reviewers/coverage.md"}]}`): `general.md` is the built-in brief and `coverage.md` asks only about test coverage. Declared reviewers run in parallel over the same candidate, each in its own session (`workflow-<run>-reviewer-<id>`), pane (`Claude: reviewer <id>`) and files (`review-<id>.*`); every one must approve. See RUNBOOK "Automatic mode: the review step" and the CHEATSHEET. `policy.json` (version 1.2.0) gives each lane its role label, owned paths, checks and `required_check_kinds` (`ui`: `build` and `browser`; `adapter`: `unit`). `launch project-workflows --workers ui` or `--workers adapter` runs one lane alone; the other lane's owned paths stay off-limits and the candidate is built from the selected lane only. The `failure_drill` names `adapter`, so a run that leaves `adapter` out records the drill as skipped.

## Automatic mode: stop at a verified feature branch

```bash
.venv/bin/python -m workflow launch project-workflows --live --automatic
```

This is the user-approved unattended path. Keep the command running in Herdr. Both implementation workers retain their interactive terminals, but have **run-scoped permission bypass and Bash access**. Global Claude settings are untouched. Worktrees are not OS sandboxes: these workers have the account's shell privileges, so only use this mode in a trusted environment.

Workers emit an explicit run/node/token-bound completion file. Idle alone is insufficient. The controller freezes completed work, executes the real isolated and combined checks, and launches a fresh read-only Claude reviewer from the LangGraph review node: by default a third native session (`workflow-<run>-reviewer` in `review-worktree/`, tools Read/Glob/Grep plus a single allowed write of `review.completion.json`) with its own `Claude: reviewer` pane in the run's tab, or a headless `claude --print` job with `--reviewer-transport print`. The reviewer reports its verdict only through a completion file bound to the run, launch token, bundle hash and candidate commit, validated against `contracts/workflow/reviewCompletion.schema.json`; the review is bound to the exact candidate and evidence hash. Only a passing review permits fast-forwarding the newly created `feature/…` branch. **No merge to main and no push.**

The automatic supervisor restarts the controller in a new Python process after a persisted step. The intentional first adapter verification failure is retried using the same SQLite thread; successful sibling work is reused. Controller PIDs are recorded in the event timeline. This is the existing LangGraph pipeline—not Pi subagent orchestration.

Bounds: per-worker deadlines measured from launch to completion signal (default 4 hours, `--worker-timeout-seconds`, at most 24 hours; persisted launch times survive restart and are enforced only while the supervisor is running), a reviewer process timeout (default 30 minutes, `--review-timeout-seconds`), existing per-check timeouts, three check attempts per lane/phase and at most 45 controller-step processes per supervisor invocation. There is no token cap or billing/provider fallback. Ambiguous launches, missing completion signals, quota blocks, reviewer rejection, ownership violations and exhausted retries stop with retained evidence. Review/worker processes are not blindly relaunched. A stopped/crashed controller cannot enforce process deadlines while it is offline.

These retries rerun verification of immutable code; they are **not** an automatic source-repair loop. Persistent code failures or review findings require intervention. Fully automatic means no routine approval prompts on the successful path, not a guarantee that every run succeeds.

Interrupting the supervisor (Ctrl-C, a closed terminal, a dropped SSH session) does **not** stop the workers: they keep running in their native terminals, the timeline records `interrupted`, and the deadline keeps counting from launch. Resume the same run with the command below. Deadline expiry, a worker reporting `blocked`, a native quota block or an invalid completion file **do** stop both workers; those runs are retained for inspection but cannot be resumed, so start a new `--run-id`.

